30	/** Freezes the SETTLED claim again at the due it would have today as an OPEN claim bound by no
31	 *  statement: its person's grade rate in force on its date, rounded as the sheet's policy date has
32	 *  it, at least the sheet's floor (none for a correction), plus the late charge it would have now.
33	 *  Stores it and logs a SETTLED line, by the user; refused when another user moved it on first. */
34	public class ApplyResettle {
35	    public void apply(@Val ResettleInput input, @Val Claim claim, ClaimStore store, ClaimLogStore log,
36	            PersonStore people, RateStore rates, SettingStore settings, SheetStore sheets,
37	            Out<Resettlement> resettlement) throws InvalidSheetException {
38	        if (!store.move(claim, ClaimStatus.SETTLED, ClaimStatus.SETTLED)) {
39	            throw new InvalidSheetException("Only a SETTLED claim can be re-settled");
40	        }
41	        String sheetId = claim.getSheetId();
42	        Claim open = new Claim(claim.getId(), sheetId, claim.getPersonId(), claim.getAmount(), claim.getDate(),
43	                claim.getNote(), ClaimStatus.OPEN, claim.getNumber(), null, claim.getOpenedBy(), false, null,
44	                claim.getCorrects(), claim.getDueBy());
45	        Person person = people.find(sheetId, claim.getPersonId());
46	        BigDecimal pct = person == null ? null : rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
47	        BigDecimal now = Lateness.of(sheetId, settings, sheets, store).due(open, pct);
48	        BigDecimal old = claim.getSettledDue();
49	        claim.setSettledDue(now);
50	        store.save(claim);
51	        log.record(claim, input.user());
52	        resettlement.set(new Resettlement(old, now));
