56	/** Moves the claim to the new status, refusing a change its current status does not allow. Opening
57	 *  gives the claim its next number (see {@link Numbering}) and records who opened it; a voided claim keeps its number, which is never reused. Settling fixes its due at its person's
58	 *  grade rate in force on the claim's date, rounded as the sheet's policy date has it and at least the sheet's floor (none when no rate of the grade applies then),
59	 *  or at the figure its person's last statement bound it to, plus the late charge it has then (frozen in).
60	 *  A clerk's settle above the clerk limit makes it PENDING instead (see {@link CheckClerkLimit}); a steward's
61	 *  approval settles a PENDING claim, frozen then at its live figure (a statement does not bind it while
62	 *  PENDING), and a rejection moves it back to OPEN, bound again by its person's last statement if that included it.
63	 *  The user who opened a claim may not settle or approve it, and a claim deferred on the sheet's today may not be settled. */
64	public class ApplyStatus {
65	    public void apply(@Val StatusInput input, @Val StatusMove move, @Val Claim claim, ClaimStore store, PersonStore people,
66	            RateStore rates, SettingStore settings, SheetStore sheets, PeriodStore periods,
67	            Out<StatusChange> change)
68	            throws InvalidSheetException {
69	        ClaimStatus from = move.from();
70	        ClaimStatus to = move.to();
71	        if (input.status() == ClaimStatus.SETTLED && claim.getOpenedBy() != null
72	                && claim.getOpenedBy().equals(input.user())) {
73	            throw new InvalidSheetException("The user who opened a claim cannot "
74	                    + (input.review() ? "approve" : "settle") + " it");
75	        }
76	        if (input.status() == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(claim.getSheetId()))) {
77	            throw new InvalidSheetException("A deferred claim cannot be settled until " + claim.getDeferredUntil());
78	        }
79	        if (!from.canBecome(to) || !store.move(claim, from, to)) {
80	            throw new InvalidSheetException("A " + from + " claim cannot become " + to);
81	        }
82	        // The due to freeze is worked out while the claim is still OPEN or PENDING, so it takes its late charge in.
83	        BigDecimal settledDue = null;
84	        if (to == ClaimStatus.SETTLED) {
85	            Person person = people.find(claim.getSheetId(), claim.getPersonId());
86	            BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
87	            settledDue = Lateness.of(claim.getSheetId(), settings, sheets, store).due(claim, pct);
88	        }
89	        claim.setStatus(to);
90	        if (from == ClaimStatus.DRAFT && to == ClaimStatus.OPEN) {
91	            claim.setNumber(Numbering.next(claim.getSheetId(), claim.getDate(), store, settings, sheets, periods));
92	            claim.setOpenedBy(input.user());
93	        }
94	        if (to == ClaimStatus.SETTLED) {
95	            claim.setSettledDue(settledDue);
96	        }
97	        change.set(new StatusChange(claim.getNumber()));
98	    }
99	}
