258	/** Works out the move a status change makes. A clerk settling an OPEN claim whose due is above the
259	 *  sheet's clerk limit sends it to PENDING instead. A claim whose due is n/a is within any limit; a
260	 *  sheet with no limit, and a steward, settle anything. Only a steward reviews a PENDING claim, and
261	 *  only a review moves it to SETTLED or back to OPEN; a review of a claim that is not PENDING is refused. */
262	public class CheckClerkLimit {
263	    public void check(@Val StatusInput input, @Val Claim claim, RoleStore roles, SettingStore settings,
264	            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims, Out<StatusMove> move)
265	            throws InvalidSheetException {
266	        ClaimStatus from = claim.getStatus();
267	        boolean steward = roles.find(claim.getSheetId(), input.user()) == Role.STEWARD;
268	        if (input.review()) {
269	            if (from != ClaimStatus.PENDING) {
270	                throw new InvalidSheetException("Only a PENDING claim can be approved or rejected");
271	            }
272	            if (!steward) {
273	                throw new InvalidSheetException("Only a steward can approve or reject a claim");
274	            }
275	            move.set(new StatusMove(from, input.status()));
276	            return;
277	        }
278	        if (from == ClaimStatus.PENDING && input.status() != ClaimStatus.VOID) {
279	            throw new InvalidSheetException("A PENDING claim waits for a steward to approve or reject it");
280	        }
281	        move.set(new StatusMove(from, overLimit(input, claim, steward, settings, people, rates, sheets, claims)
282	                ? ClaimStatus.PENDING : input.status()));
283	    }
284	    private static boolean overLimit(StatusInput input, Claim claim, boolean steward, SettingStore settings,
285	            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims) {
286	        if (input.status() != ClaimStatus.SETTLED || claim.getStatus() != ClaimStatus.OPEN || steward) {
287	            return false;
288	        }
289	        BigDecimal limit = settings.clerkLimit(claim.getSheetId());
290	        if (limit == null) {
291	            return false;
292	        }
293	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
294	        BigDecimal pct = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
295	        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims).due(claim, pct);
296	        return due != null && due.compareTo(limit) > 0;
297	    }
298	}
