409	 *  to (not while it is PENDING, which a statement does not bind), else its live due: its amount at the grade rate in force on its date, rounded as the sheet's
410	 *  {@link Rounding} has it, and
411	 *  at least the sheet's floor, except a correction's, which has no floor (null, n/a, when no rate applies). */
412	public final class ClaimFigure {
413	    private ClaimFigure() {
414	    }
415	    /** amount × pct ÷ 100, rounded by {@code mode} to two decimals; null when there is no rate. */
416	    public static BigDecimal of(BigDecimal amount, BigDecimal pct, RoundingMode mode) {
417	        return pct == null ? null : amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, mode);
418	    }
419	    /** The live due: amount at pct, raised to the floor; null when there is no rate. */
420	    public static BigDecimal of(BigDecimal amount, BigDecimal pct, BigDecimal floor, RoundingMode mode) {
421	        BigDecimal due = of(amount, pct, mode);
422	        return due == null || due.compareTo(floor) >= 0 ? due : floor.setScale(2);
423	    }
424	    /** The figure the claim has now, given the grade's rate in force on its date and the sheet's floor. */
425	    public static BigDecimal of(Claim claim, BigDecimal pct, BigDecimal floor, Rounding rounding) {
426	        if (claim.getSettledDue() != null) {
427	            return claim.getSettledDue();
428	        }
429	        if (claim.isBound()) {
430	            return claim.getStatedDue();
431	        }
432	        RoundingMode mode = rounding.mode(claim);
433	        return claim.isCorrection() ? of(claim.getAmount(), pct, mode) : of(claim.getAmount(), pct, floor, mode);
434	    }
