637	/** Where a claim stands. Only OPEN, PENDING and SETTLED claims count toward the totals; a PENDING claim
638	 *  (settled by a clerk above the clerk limit, awaiting a steward) is handled as an OPEN one, except
639	 *  that a statement does not bind it while it is PENDING. */
640	public enum ClaimStatus {
641	    DRAFT, OPEN, PENDING, SETTLED, VOID;
642	    /** Whether a claim may move from this status to {@code next}: DRAFT to OPEN, OPEN to PENDING or
643	     *  SETTLED, PENDING to SETTLED (approved) or OPEN (rejected), and DRAFT, OPEN or PENDING to VOID.
644	     *  SETTLED and VOID are final. */
645	    public boolean canBecome(ClaimStatus next) {
646	        return switch (next) {
647	            case OPEN -> this == DRAFT || this == PENDING;
648	            case PENDING -> this == OPEN;
649	            case SETTLED -> this == OPEN || this == PENDING;
650	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
651	            case DRAFT -> false;
652	        };
653	    }
654	    /** Whether a claim of this status may move to another person: DRAFT, OPEN or PENDING. */
655	    public boolean canMove() {
656	        return this == DRAFT || this == OPEN || this == PENDING;
657	    }
658	    /** Whether the claim is open: OPEN, or PENDING, which is handled as open. */
659	    public boolean isOpen() {
660	        return this == OPEN || this == PENDING;
661	    }
662	    /** The audit event recorded when a claim moves to this status. */
663	    public String event() {
664	        return switch (this) {
665	            case OPEN -> "CLAIM_OPENED";
666	            case PENDING -> "CLAIM_PENDING";
667	            case SETTLED -> "CLAIM_SETTLED";
668	            case VOID -> "CLAIM_VOIDED";
669	            case DRAFT -> "CLAIM_DRAFTED";
670	        };
671	    }
672	    /** The audit event recorded when a claim moves from {@code from} to this status: a PENDING claim
673	     *  settled is CLAIM_APPROVED, and one moved back to OPEN is CLAIM_REJECTED. */
674	    public String event(ClaimStatus from) {
675	        if (from == PENDING && this == SETTLED) {
676	            return "CLAIM_APPROVED";
677	        }
678	        if (from == PENDING && this == OPEN) {
679	            return "CLAIM_REJECTED";
680	        }
681	        return event();
682	    }
683	}
