828	 *  figure for every full 30 days it is overdue, rounded as the sheet's {@link Rounding} has the claim. The charge is never bound by a
829	 *  statement; settling freezes it into the settled due. */
830	public record Lateness(Function<LocalDate, BigDecimal> latePcts, Function<LocalDate, BigDecimal> floors,
831	        LocalDate today, Rounding rounding) {
832	    /** The days in each step of the late charge. */
833	    private static final int PERIOD_DAYS = 30;
834	    public static Lateness of(String sheetId, SettingStore settings, SheetStore sheets, ClaimStore claims) {
835	        return new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), sheets.today(sheetId),
836	                Rounding.of(sheetId, settings, sheets, claims));
837	    }
838	    /** The late charge on a claim whose figure (bound, else floored live) is {@code figure}; none on
839	     *  a correction. */
840	    public BigDecimal charge(Claim claim, BigDecimal figure) {
841	        if (figure == null || !claim.getStatus().isOpen() || today == null || claim.isCorrection()
842	                || claim.isDeferredOn(today)) {
843	            return BigDecimal.ZERO.setScale(2);
844	        }
845	        long overdue = ChronoUnit.DAYS.between(claim.getDueBy(), today);
846	        long periods = overdue <= 0 ? 0 : overdue / PERIOD_DAYS;
847	        return ClaimFigure.of(figure, latePcts.apply(claim.getDate()).multiply(BigDecimal.valueOf(periods)), rounding.mode(claim));
848	    }
849	    /** The floor in force on the claim's date. */
850	    public BigDecimal floor(Claim claim) {
851	        return floors.apply(claim.getDate());
852	    }
853	    /** The claim's due now: its figure, plus the late charge unless settled (its settled due has it). */
854	    public BigDecimal due(Claim claim, BigDecimal pct) {
855	        BigDecimal figure = ClaimFigure.of(claim, pct, floor(claim), rounding);
856	        if (figure == null || claim.getSettledDue() != null) {
857	            return figure;
858	        }
859	        return figure.add(charge(claim, figure));
860	    }
861	}
