889	    public static String next(String sheetId, LocalDate claimDate, ClaimStore claims, SettingStore settings,
890	            SheetStore sheets, PeriodStore periods) {
891	        LocalDate from = settings.periodNumberingFrom(sheetId);
892	        if (from == null || sheets.today(sheetId).isBefore(from)) {
893	            return String.valueOf(claims.nextNumber(sheetId));
894	        }
