903	/** Opens each selected claim that can be opened, in list order: its people in the order they were
904	 *  added, a person's claims newest first. Each is opened as a single open would be (its next
905	 *  number, opened-by the user) and recorded as CLAIM_OPENED, then how it moved the sheet's figures.
906	 *  A claim that is not on the sheet, is not a DRAFT, or is dated in a closed period is refused and
907	 *  left as it is. */
908	public class OpenClaims {
909	    public void open(@PathVariable("sheetId") String sheetId, @Val BulkOpenInput input, ClaimStore store,
910	            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, ClaimLogStore log, RollupService rollups, Audit audit, Out<BulkOpenResult> result) {
911	        String sheet = sheetId.trim();
912	        Map<Long, Integer> personOrder = new HashMap<>();
913	        Map<Long, Person> persons = new HashMap<>();
914	        for (Person person : people.list(sheet)) {
915	            personOrder.put(person.getId(), personOrder.size());
916	            persons.put(person.getId(), person);
917	        }
918	        int refused = 0;
919	        List<Claim> selected = new ArrayList<>();
920	        for (Long id : input.claimIds()) {
921	            Claim claim = id == null ? null : store.find(sheet, id);
922	            if (claim == null) {
923	                refused++;
924	            } else {
925	                selected.add(claim);
926	            }
927	        }
928	        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
929	                .thenComparing(Comparator.comparingLong(Claim::getId).reversed()));
930	        int opened = 0;
931	        for (Claim claim : selected) {
932	            if (claim.getStatus() != ClaimStatus.DRAFT || closed(periods, claim)) {
933	                refused++;
934	                continue;
935	            }
936	            Rollup before = rollups.snapshot(sheet);
937	            if (!store.move(claim, claim.getStatus(), ClaimStatus.OPEN)) {
938	                refused++;
939	                continue;
940	            }
941	            claim.setStatus(ClaimStatus.OPEN);
942	            claim.setNumber(Numbering.next(sheet, claim.getDate(), store, settings, sheets, periods));
943	            claim.setOpenedBy(input.user());
944	            store.save(claim);
945	            log.record(claim, input.user());
946	            Person person = persons.get(claim.getPersonId());
947	            ClaimResponse shown = ClaimResponse.from(claim);
948	            audit.record(ClaimStatus.OPEN.event() + " sheet=" + sheet + " by=" + input.user() + " person="
949	                    + (person == null ? "" : person.getName()) + " amount=" + shown.amount() + " date=" + shown.date()
950	                    + " number=" + claim.getNumber());
951	            rollups.record(sheet, input.user(), before);
952	            opened++;
953	        }
954	        result.set(new BulkOpenResult(opened, refused));
955	    }
956	    private static boolean closed(PeriodStore periods, Claim claim) {
957	        try {
958	            CheckClaimPeriod.refuseClosed(periods, claim.getSheetId(), claim.getDate());
959	            return false;
960	        } catch (InvalidSheetException e) {
961	            return true;
962	        }
963	    }
964	}
