1024	/** How a sheet rounds a claim's live figures (its rate step and late charge): a claim dated before the
1025	 *  sheet's policy date (the one set, else the sheet's today) rounds half up, one dated on or after it
1026	 *  half to even. A correction rounds by the date of the claim it corrects, not its own. */
1027	public final class Rounding {
1028	    private final LocalDate policyDate;
1029	    /** The date of each opened claim on the sheet, by its person and number. */
1030	    private final Map<String, LocalDate> dates = new HashMap<>();
1031	    public Rounding(LocalDate policyDate, List<Claim> claims) {
1032	        this.policyDate = policyDate;
1033	        for (Claim claim : claims) {
1034	            if (claim.getNumber() != null) {
1035	                dates.put(key(claim.getPersonId(), claim.getNumber()), claim.getDate());
1036	            }
1037	        }
1038	    }
1039	    /** The sheet's rounding, knowing every claim on it (so a correction finds the claim it corrects). */
1040	    public static Rounding of(String sheetId, SettingStore settings, SheetStore sheets, ClaimStore claims) {
1041	        LocalDate policy = settings.policyDate(sheetId);
1042	        return new Rounding(policy != null ? policy : sheets.today(sheetId), claims.list(sheetId));
1043	    }
1044	    /** The date the claim rounds by: its own, or for a correction the date of the claim it corrects. */
1045	    public LocalDate date(Claim claim) {
1046	        LocalDate date = claim.getDate();
1047	        if (claim.getCorrects() != null) {
1048	            date = dates.getOrDefault(key(claim.getPersonId(), claim.getCorrects()), date);
1049	        }
1050	        return date;
1051	    }
1052	    /** The rounding of the claim's live figures. */
1053	    public RoundingMode mode(Claim claim) {
1054	        return policyDate != null && date(claim).isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
1055	    }
1056	    private static String key(long personId, String number) {
1057	        return personId + "/" + number;
1058	    }
1059	}
