1106	            personOrder.put(person.getId(), personOrder.size());
1107	        }
1108	        int refused = 0;
1109	        List<Claim> selected = new ArrayList<>();
1110	        for (Long id : input.claimIds()) {
1111	            Claim claim = id == null ? null : store.find(sheet, id);
1112	            if (claim == null) {
1113	                refused++;
1114	            } else {
1115	                selected.add(claim);
1116	            }
1117	        }
