1135	/** Takes a statement of the person on the sheet's today: their due-total (the sum of the figures of
1136	 *  their claims that count; n/a when their grade in force today has no rate today and no counting claim
1137	 *  keeps a fixed figure or a figure at another grade, the one in force on its date), binding each counting claim to its figure now (its floored live due when not fixed) and unbinding the rest. A settled
1138	 *  claim keeps its fixed figure. The due-total includes the late charges of overdue claims, but a
1139	 *  claim is bound to its figure without its charge, which keeps following the sheet's today. The
1140	 *  due-total is at most the sheet's cap. */
1141	public class TakeStatement {
1142	    public void take(@Val StatementRequest request, @Val Person person, ClaimStore claims, RateStore rates,
1143	            SheetStore sheets, SettingStore settings, StatementStore statements, Out<Statement> statementOut) {
1144	        String sheetId = person.getSheetId();
1145	        LocalDate today = sheets.today(sheetId);
1146	        Rounding rounding = Rounding.of(sheetId, settings, sheets, claims);
1147	        Lateness lateness = new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), today, rounding);
1148	        BigDecimal total = BigDecimal.ZERO.setScale(2);
1149	        boolean fixed = false;
1150	        int counted = 0;
1151	        // Locked, so a status change or another statement made at once waits for this one.
1152	        for (Claim claim : claims.listForUpdate(sheetId, person.getId())) {
1153	            // An OPEN (or PENDING) claim dated within a hold counts in no live total unless a statement bound
1154	            // it, so a statement neither counts nor binds it; one it bound before stays counted. A deferred
1155	            // claim counts in no total until the sheet's today reaches its date: a statement leaves it unbound.
1156	            boolean counts = RollupService.counts(claim, person, today);
1157	            BigDecimal figure = null;
1158	            if (counts) {
1159	                figure = ClaimFigure.of(claim, rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()), lateness.floor(claim), rounding);
1160	                counted++;
1161	                if (figure != null) {
1162	                    total = total.add(claim.getSettledDue() != null ? figure : figure.add(lateness.charge(claim, figure)));
1163	                }
1164	                // A figure at a grade other than the one in force today, or at a rate that ended before
1165	                // today, does not hang on today's grade's rate.
1166	                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
1167	                        || (figure != null && (!person.gradeOn(claim.getDate()).equals(person.gradeOn(today))
1168	                                || rates.endsBefore(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), today)));
1169	            }
1170	            // A claim whose rate ended before its date is bound to n/a, so a later rate leaves it so.
1171	            boolean na = counts && figure == null && (claim.isBound()
1172	                    || (claim.getSettledDue() == null && rates.ended(sheetId, person.gradeOn(claim.getDate()), claim.getDate())));
1173	            claim.setStated(counts);
1174	            claim.setStatedDue(figure);
1175	            claim.setStatedNa(na);
1176	            claims.bind(claim);
1177	        }
1178	        boolean na = rates.find(sheetId, person.gradeOn(today), today) == null && !fixed;
1179	        Statement statement = new Statement(person.getId(), today,
1180	                na ? null : SettingStore.capped(total, settings.cap(sheetId)), counted);
1181	        statements.add(sheetId, statement, request.user());
1182	        statementOut.set(statement);
1183	    }
1184	}
