1652	/**
1653	 * Works out the sheet's figures as the screen shows them, and records in the audit file how a change
1654	 * moved them: ROLLUP sheet=<id> by=<user> person=<name> claimed=<0.00> due-total=<0.00 or n/a>
1655	 * overdue-total=<0.00> for each person whose figures changed (a person new to the sheet counts as changed), in
1656	 * the order they were added, then TOTALS sheet=<id> by=<user> claimed-total=<0.00> due-total=<0.00>
1657	 * overdue-total=<0.00> when any of the sheet's totals changed. A person's overdue-total is the due (late charge
1658	 * included, skipping n/a) of their counting claims that are OPEN or PENDING with a due-by before today. A person's due-total is at most the sheet's cap. A change that moves no figure records nothing here.
1659	 */
1660	@Service
1661	public class RollupService {
1662	    private static final String NA = "n/a";
1663	    private final PersonStore people;
1664	    private final ClaimStore claims;
1665	    private final RateStore rates;
1666	    private final SheetStore sheets;
1667	    private final SettingStore settings;
1668	    private final Audit audit;
1669	    public RollupService(PersonStore people, ClaimStore claims, RateStore rates, SheetStore sheets, SettingStore settings,
1670	            Audit audit) {
1671	        this.people = people;
1672	        this.claims = claims;
1673	        this.rates = rates;
1674	        this.sheets = sheets;
1675	        this.settings = settings;
1676	        this.audit = audit;
1677	    }
1678	    /** The sheet's figures as the store holds them now. */
1679	    public Rollup snapshot(String sheetId) {
1680	        LocalDate today = sheets.today(sheetId);
1681	        List<Claim> all = claims.list(sheetId);
1682	        BigDecimal cap = settings.cap(sheetId);
1683	        Lateness lateness = new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), sheets.today(sheetId),
1684	                new Rounding(policyDate(sheetId), all));
1685	        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
1686	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
1687	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
1688	        BigDecimal overdueTotal = BigDecimal.ZERO.setScale(2);
1689	        for (Person person : people.list(sheetId)) {
1690	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
1691	            BigDecimal due = BigDecimal.ZERO.setScale(2);
1692	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
1693	            boolean fixed = false;
1694	            for (Claim claim : all) {
1695	                if (claim.getPersonId() != person.getId()
1696	                        || !counts(claim, person, today)) {
1697	                    continue;
1698	                }
1699	                claimed = claimed.add(claim.getAmount());
1700	                BigDecimal figure = lateness.due(claim, rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
1701	                if (figure != null) {
1702	                    due = due.add(figure);
1703	                    if (overdue(claim, today)) {
1704	                        overdue = overdue.add(figure);
1705	                    }
1706	                }
1707	                // A figure at a grade other than the one in force today, or at a rate that ended before
1708	                // today, does not hang on today's grade's rate.
1709	                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
1710	                        || (figure != null && (!person.gradeOn(claim.getDate()).equals(person.gradeOn(today))
1711	                                || rates.endsBefore(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), today)));
1712	            }
1713	            boolean na = rates.find(sheetId, person.gradeOn(today), today) == null && !fixed;
1714	            claimedTotal = claimedTotal.add(claimed);
1715	            overdueTotal = overdueTotal.add(overdue);
1716	            due = SettingStore.capped(due, cap);
1717	            if (!na) {
1718	                dueTotal = dueTotal.add(due);
1719	            }
1720	            figures.put(person.getId(), new Rollup.Figures(person.getName(), shown(claimed), na ? NA : shown(due),
1721	                    shown(overdue)));
1722	        }
1723	        return new Rollup(figures, shown(claimedTotal), shown(dueTotal), shown(overdueTotal));
1724	    }
1725	    /** Each person's due-total of their claims that count dated from..to (inclusive), by person id in
1726	     *  the order they were added: the sum of their figures, skipping n/a, as the screen shows a person's
1727	     *  due-total for a period. A period's due-total is the sum of these. */
1728	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
1729	        LocalDate today = sheets.today(sheetId);
1730	        List<Claim> all = claims.list(sheetId);
1731	        Lateness lateness = new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), today,
1732	                new Rounding(policyDate(sheetId), all));
1733	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
1734	        for (Person person : people.list(sheetId)) {
1735	            BigDecimal total = BigDecimal.ZERO.setScale(2);
1736	            for (Claim claim : all) {
1737	                if (claim.getPersonId() != person.getId()
1738	                        || !counts(claim, person, today)
1739	                        || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
1740	                    continue;
1741	                }
1742	                BigDecimal figure = lateness.due(claim, rates.find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
1743	                if (figure != null) {
1744	                    total = total.add(figure);
1745	                }
1746	            }
1747	            totals.put(person.getId(), total);
1748	        }
1749	        return totals;
1750	    }
1751	    /** Records how the sheet's figures moved since {@code before}, the change made by {@code user}. */
1752	    public void record(String sheetId, String user, Rollup before) {
1753	        Rollup after = snapshot(sheetId);
1754	        String who = " sheet=" + sheetId + " by=" + user;
1755	        after.people().forEach((id, now) -> {
1756	            if (!now.sameAs(before.people().get(id))) {
1757	                audit.record("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed() + " due-total="
1758	                        + now.dueTotal() + " overdue-total=" + now.overdueTotal());
1759	            }
1760	        });
1761	        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
1762	                || !after.overdueTotal().equals(before.overdueTotal())) {
1763	            audit.record("TOTALS" + who + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal()
1764	                    + " overdue-total=" + after.overdueTotal());
1765	        }
1766	    }
1767	    /** Whether the claim is overdue: OPEN (or PENDING), not deferred, with its due-by before the sheet's today. */
1768	    private static boolean overdue(Claim claim, LocalDate today) {
1769	        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && today != null && claim.getDueBy() != null
1770	                && claim.getDueBy().isBefore(today);
1771	    }
1772	    /** The date the sheet's rounding turns on: the policy date set, else the sheet's today. */
1773	    private LocalDate policyDate(String sheetId) {
1774	        LocalDate policy = settings.policyDate(sheetId);
1775	        return policy != null ? policy : sheets.today(sheetId);
1776	    }
1777	    /** Only OPEN, PENDING and SETTLED claims count, and an OPEN or PENDING claim dated within one of its
1778	     *  person's holds does not, unless a statement bound it; nor does an OPEN claim deferred on the sheet's today. */
1779	    public static boolean counts(Claim claim, Person person, LocalDate today) {
1780	        return claim.getStatus() == ClaimStatus.SETTLED
1781	                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
1782	                        && (claim.isStated() || !person.heldOn(claim.getDate())));
1783	    }
1784	    private static String shown(BigDecimal value) {
1785	        return value.setScale(2).toPlainString();
1786	    }
1787	}
