1796	/**
1797	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
1798	 * so tests can assert side-effects by reading that file — the second test-assertion channel
1799	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
1800	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
1801	 *
1802	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
1803	 * SYNC) so a test reads the record immediately.
1804	 */
1805	@Service
1806	public class Audit {
1807	    private final Path file;
1808	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
1809	        this.file = Path.of(path);
1810	    }
1811	    /** Append one audit record. Tests assert the exact line(s) in the file. */
1812	    public synchronized void record(String entry) {
1813	        try {
1814	            Path parent = file.toAbsolutePath().getParent();
1815	            if (parent != null) {
1816	                Files.createDirectories(parent);
1817	            }
1818	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
1819	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
1820	        } catch (IOException e) {
1821	            throw new UncheckedIOException(e);
1822	        }
1823	    }
1824	    /** Remove the audit file. */
1825	    public synchronized void clear() {
1826	        try {
1827	            Files.deleteIfExists(file);
1828	        } catch (IOException e) {
1829	            throw new UncheckedIOException(e);
1830	        }
1831	    }
1832	}
