/** A grade's rate: `pct` is a percent with two decimals; `from` (yyyy-MM-dd) is the date it applies
 *  from, null for from the beginning of time; `to` the date it applies through, null for no end. A
 *  grade may have several; one with no rate has none. */
export type Rate = { grade: string; pct: string; from: string | null; to: string | null };
/** Under the sheet's key, so loading the sheet again re-reads its rates. */
export const ratesKey = (sheet: string) => [...sheetKey(sheet), 'rates'] as const;
export function useRates(sheet: string) {
  return useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    enabled: sheet !== '',
  });
}
/** The grade's percent in force on the date (yyyy-MM-dd): the rate with the latest from-date on or
 *  before it, or undefined when none of the grade's rates applies then, or that rate ended (its to-date) before it. */
export function rateOf(rates: Rate[] | undefined, grade: string, on: string | undefined): string | undefined {
  if (on === undefined) return undefined;
  let best: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > on)) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best === undefined || (best.to !== null && best.to < on) ? undefined : best.pct;
}
/** Whether the grade's rate in force on the date ends before `today`: its to-date, or the day before the
 *  grade's next rate starts, whichever is first, is before it. */
export function endsBefore(rates: Rate[] | undefined, grade: string, on: string, today: string): boolean {
  let best: Rate | undefined;
  let next: string | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade) continue;
    if (r.from !== null && r.from > on) {
      if (next === undefined || r.from < next) next = r.from;
    } else if (best === undefined || (best.from ?? '') < (r.from ?? '')) {
      best = r;
    }
  }
  if (best === undefined) return false;
  return (best.to !== null && best.to < today) || (next !== undefined && next <= today);
}
export const NA = 'n/a';
/** Whole hundredths of a two-decimal number, read exactly from its text. */
function hundredths(value: string): bigint {
  const [whole, frac = ''] = value.trim().replace(/^-/, '').split('.');
  const n = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return value.trim().startsWith('-') ? -n : n;
}
/** Hundredths as text with two decimals. */
function format(cents: bigint): string {
  const neg = cents < 0n;
  const abs = neg ? -cents : cents;
  return `${neg ? '-' : ''}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
}
/** amount × pct ÷ 100, rounded half to even (half up when `halfUp`) to two decimals; n/a when there is no rate. */
export function due(amount: string, pct: string | undefined, halfUp = false): string {
  if (pct === undefined) return NA;
  // amount (hundredths) × pct (hundredths) is in units of 1/10000 cent-percent: ÷ 10000 gives cents.
  const product = hundredths(amount) * hundredths(pct);
  const abs = product < 0n ? -product : product;
  const rest = abs % 10000n;
  let cents = abs / 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  return format(product < 0n ? -cents : cents);
}
/** A live due: amount at pct (see `due`), raised to the sheet's floor (two decimals) when below it;
 *  n/a when there is no rate. */
export function liveDue(amount: string, pct: string | undefined, floor: string | undefined, halfUp = false): string {
  const d = due(amount, pct, halfUp);
  if (d === NA || floor === undefined || hundredths(d) >= hundredths(floor)) return d;
  return format(hundredths(floor));
}
/** The sum of these dues, skipping n/a; two decimals. */
export function dueTotal(dues: string[]): string {
  return format(dues.filter((d) => d !== NA).reduce((sum, d) => sum + hundredths(d), 0n));
}
/** What a claim's late charge follows: the sheet's late percent (two decimals) in force on the claim's date
 *  and how many full 30 days the claim is overdue; and whether the claim's live figures round half up (else half to even). */
export type Late = { pct: ((claim: Claim) => string) | undefined; periods: (claim: Claim) => number; halfUp?: (claim: Claim) => boolean };
/** The sheet's floor (two decimals) in force on a date; undefined for none known. */
export type Floor = ((date: string) => string) | undefined;
/** The late charge on a figure: the late percent of it for every full 30 days overdue, rounded like due. */
function lateCharge(claim: Claim, figure: string, late: Late | undefined): string | undefined {
  const periods = late?.pct === undefined || isCorrection(claim) ? 0 : late.periods(claim);
  if (periods <= 0 || figure === NA) return undefined;
  return due(figure, format(hundredths(late!.pct!(claim)) * BigInt(periods)), late?.halfUp?.(claim) ?? false);
}
/** Whether the claim keeps a figure whatever the rates: fixed when settled, or bound by a statement to a
 *  figure (bound to n/a keeps no figure). */
const fixed = (claim: Claim) => claim.due !== null || (isBound(claim) && claim.statedDue !== null);
/** A claim's due: the due fixed when it was settled (its late charge frozen in), else its figure — the
 *  figure its person's last statement bound it to (not while PENDING), else its live due: its amount at the rate in force
 *  on the claim's date of its person's grade in force on that date, at least the sheet's floor in force on that date — plus its late charge when overdue.
 *  A correction's live due has no floor and it has no late charge.
 *  A statement never binds the charge: it keeps following the sheet's today. */
export function claimDue(
  claim: Claim,
  rates: Rate[] | undefined,
  grades: Grades,
  floor: Floor,
  late?: Late,
): string {
  if (claim.due !== null) return claim.due;
  const pct = rateOf(rates, gradeOn(grades, claim.date), claim.date);
  const halfUp = late?.halfUp?.(claim) ?? false;
  const figure = isBound(claim)
    ? claim.statedDue ?? NA
    : isCorrection(claim) ? due(claim.amount, pct, halfUp) : liveDue(claim.amount, pct, floor?.(claim.date), halfUp);
  const charge = lateCharge(claim, figure, late);
  return charge === undefined ? figure : format(hundredths(figure) + hundredths(charge));
}
/** A person's due-total: the sum of the figures of their claims that count, at most the sheet's cap
 *  (two decimals; null or undefined for none). n/a when their grade
 *  in force on the sheet's today has no rate then, unless a claim that counts keeps a fixed (settled or
 *  stated) figure, or a figure at another grade (the one in force on its date), or at a rate that ended before today;
 *  n/a is not capped. */
export function personDue(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
  cap?: string | null,
): string {
  const total = uncappedDue(claims, rates, grades, today, floor, late);
  return total === NA || cap == null || hundredths(total) <= hundredths(cap) ? total : format(hundredths(cap));
}
/** A person's excess: how far the sum of their figures is above the sheet's cap; 0.00 when it is not, or
 *  there is no cap, or their due-total is n/a. */
export function personExcess(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
  cap?: string | null,
): string {
  const total = uncappedDue(claims, rates, grades, today, floor, late);
  return total === NA || cap == null || hundredths(total) <= hundredths(cap)
    ? format(0n)
    : format(hundredths(total) - hundredths(cap));
}
/** A person's due-total before the cap (see `personDue`). */
function uncappedDue(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: Floor,
  late?: Late,
): string {
  const mine = claims.filter(counts);
  const now = gradeOn(grades, today);
  const elsewhere = (c: Claim) => {
    const grade = gradeOn(grades, c.date);
    return rateOf(rates, grade, c.date) !== undefined
      && (grade !== now || (today !== undefined && endsBefore(rates, grade, c.date, today)));
  };
  if (rateOf(rates, now, today) === undefined && !mine.some((c) => fixed(c) || elsewhere(c))) {
    return NA;
  }
  return dueTotal(mine.map((c) => claimDue(c, rates, grades, floor, late)));
}
=== features/claims/claims.ts
/** PENDING: settled by a clerk above the clerk limit, awaiting a steward's approval; handled as OPEN,
 *  except that a statement does not bind it while it is PENDING. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
/** Every status the summary and header count, whether or not a claim can reach it. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const satisfies readonly ClaimStatus[];
/** How many of these claims have the status. */
export const statusCount = (claims: Claim[] | undefined, status: ClaimStatus) =>
  (claims ?? []).filter((c) => c.status === status).length;
/** `amount` has two decimals; `date` is yyyy-MM-dd; `number` is given when the claim is opened
 *  (null for a draft or a voided claim): the sheet-wide 1, 2, ... or, numbered per period, <period>-<n> / X-<n>. */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  /** The due fixed when the claim was settled; null when it has none, so its due follows the rate. */
  due: string | null;
  /** The user who opened the claim; null until it is opened. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim to its figure then. */
  stated: boolean;
  /** The figure the claim was bound to; null when not bound, or bound while it had none. */
  statedDue: string | null;
  /** Whether the statement bound the claim to n/a: the rate that would apply to it had ended (its to-date). */
  statedNa: boolean;
  /** The number of the settled claim a correction (a negative amount) corrects; null for any other claim. */
  corrects: string | null;
  /** The date (yyyy-MM-dd) its live figures round by: its own, or for a correction that of the claim it corrects. */
  roundsBy: string;
  /** The date (yyyy-MM-dd) it is due by, fixed when it was added from the terms of its person's grade then. */
  dueBy: string;
  /** Its status log, oldest first: `<STATUS> by <user> on <date> due=<due>`, one line per status it has had. */
  log: string[];
  /** Whether it is deferred on the sheet's today: OPEN and deferred until a date after it. Until then it
   *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement. */
  deferred: boolean;
  /** The date (yyyy-MM-dd) it was last deferred until; null when it was never deferred. */
  deferredUntil: string | null;
};
/** A correction: a claim with a negative amount, which has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.amount.trim().startsWith('-') && Number(c.amount) !== 0;
/** Whether the claim is open: OPEN, or PENDING, which is handled as open. */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';
/** Only OPEN, PENDING and SETTLED claims count toward claimed and the totals; a deferred claim does not. */
export const counts = (c: Claim) => (isOpen(c) && !c.deferred) || c.status === 'SETTLED';
/** Whether the claim keeps the figure (or n/a) its person's last statement bound it to: not while PENDING. */
export const isBound = (c: Claim) => c.stated && (c.statedDue !== null || c.statedNa) && c.status !== 'PENDING';
/** These claims less the OPEN (or PENDING) claims dated within one of their person's holds, which
 *  count in no live total, unless a statement bound them. */
export const live = (claims: Claim[], people: { id: number; holds: Hold[] }[] | undefined) => {
  const holds = new Map((people ?? []).map((p) => [p.id, p.holds]));
  return claims.filter((c) => !(isOpen(c) && !c.stated && (holds.get(c.personId) ?? []).some((h) => covers(h, c.date))));
};
/** Under the sheet's key, so loading the sheet again re-reads its claims. */
export const claimsKey = (sheet: string) => [...sheetKey(sheet), 'claims'] as const;
/** Every claim on the sheet, newest first. */
export function useClaims(sheet: string) {
  return useQuery({
    queryKey: claimsKey(sheet),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheet)}/claims`),
    enabled: sheet !== '',
  });
}
/** Amounts are added in whole cents, so the sum is exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);
/** The sum of the amounts of those of these claims that count, with two decimals. */
export function claimed(claims: Claim[]): string {
  return (claims.filter(counts).reduce((sum, c) => sum + cents(c.amount), 0) / 100).toFixed(2);
}
/** The ids of the claims selected for a bulk action, kept in the URL (`selectedClaims`, comma separated). */
export function useSelectedClaims(): [number[], (ids: number[]) => void] {
  const [raw, setRaw] = useSearchParam('selectedClaims', asString);
  const ids = raw.split(',').filter((s) => s !== '').map(Number).filter((n) => !Number.isNaN(n));
  return [ids, (next) => setRaw(next.join(','))];
}
=== features/people/people.ts
/** `version` moves on with each stored edit; an edit is saved only over the version its editor loaded.
 *  `statementCount` is how many statements were taken of them; `statedTotal` (two decimals, or n/a)
 *  and `statementDate` (yyyy-MM-dd) are the last one's, null when none was taken. `retired` is set
 *  as soon as a `retiredFrom` date (yyyy-MM-dd, null when not retired) is, whatever the date.
 *  `holds` are their holds, oldest first; `held` whether they have any. Their OPEN claims dated within
 *  a hold count in no live total unless a statement bound them; their SETTLED ones still do.
 *  `patronIds` are the ids of the other people on the sheet they named as their patrons.
 *  `grade` is the grade in force on the sheet's today; `grades` every grade with the date it applies from. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: Grades;
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  holds: Hold[];
  patronIds: number[];
};
/** A hold from its from-date to its to-date (yyyy-MM-dd, both inclusive; null for no end). */
export type Hold = { from: string; to: string | null };
/** Whether the hold covers the date (yyyy-MM-dd). */
export const covers = (h: Hold, date: string) => h.from <= date && (h.to === null || date <= h.to);
export const GRADES = ['A', 'B', 'C'] as const;
/** A person's grades, each with the date (yyyy-MM-dd) it applies from; the first has none (null),
 *  applying from the beginning of time. */
export type Grades = { grade: string; from: string | null }[];
/** The grade in force on the date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(grades: Grades, on: string | undefined): string {
  let best = grades[0];
  for (const g of grades) {
    if (g.from === null || (on !== undefined && g.from <= on)) {
      if ((best.from ?? '') <= (g.from ?? '')) best = g;
    }
  }
  return best?.grade ?? 'A';
}
/** Under the sheet's key, so loading the sheet again re-reads its people. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;
export function usePeople(sheet: string) {
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: sheet !== '',
  });
}
/** The id of the person whose editor is open in the person form ('' when it adds). */
export const useEditingPerson = () => useSearchParam('editPerson', asString);
/** Whether the people list shows retired people too; off when the screen is first opened. */
export const useShowRetired = () => useSearchParam('showRetired', asFlag);
=== features/overdue/overdue.ts
/** The claim's due-by (yyyy-MM-dd): fixed when it was added, from the terms of its person's grade then. */
export const dueBy = (claim: Claim): string => claim.dueBy;
/** Whether the claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by is before the sheet's today. */
export function overdue(claim: Claim, today: string | undefined): boolean {
  return isOpen(claim) && !claim.deferred && today !== undefined && dueBy(claim) < today;
}
const DAY = 24 * 60 * 60 * 1000;
/** How many full 30 days the claim is overdue on the sheet's today (0 when it is not overdue). */
export function latePeriods(claim: Claim, today: string | undefined): number {
  if (today === undefined || !overdue(claim, today)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${dueBy(claim)}T00:00:00Z`)) / DAY;
  return Math.floor(days / 30);
}
/** What the sheet's late charge follows: its late percent in force on each claim's date, each claim's due-by and its today; and how it rounds:
 *  a claim rounding by a date before the policy date (else the sheet's today) rounds half up. */
export function lateOf(settings: Settings | undefined, today: string | undefined): Late {
  const policy = settings?.policyDate ?? today;
  const pcts = latePctOf(settings);
  return {
    pct: pcts && ((c) => pcts(c.date)),
    periods: (c) => latePeriods(c, today),
    halfUp: (c) => policy !== undefined && (c.roundsBy ?? c.date) < policy,
  };
}
/** A person's overdue claims among these (their claims that count): how many, and the sum of their
 *  dues (late charge included) at the person's grade in force on each claim's date, skipping n/a. */
export function overdueFigures(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  floor: Floor,
  today: string | undefined,
  lateCharge?: Late,
): { count: number; total: string } {
  const late = claims.filter((c) => overdue(c, today));
  return { count: late.length, total: dueTotal(late.map((c) => claimDue(c, rates, grades, floor, lateCharge))) };
}
=== features/periods/periods.ts
/** A period: its name (unique on the sheet), its from and to dates (yyyy-MM-dd, inclusive), whether
 *  it is closed and, once closed, the due-total fixed on closing (null while open) and each person's
 *  due-total fixed on closing, by person id (empty while open). No two periods on a sheet overlap. */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  total: string | null;
  people: Record<string, string>;
};
/** Under the sheet's key, so loading the sheet again re-reads its periods. */
export const periodsKey = (sheet: string) => [...sheetKey(sheet), 'periods'] as const;
/** Every period on the sheet, by from-date. */
export function usePeriods(sheet: string) {
  return useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    enabled: sheet !== '',
  });
}
/** Whether the date (yyyy-MM-dd) falls in the period. */
export const contains = (period: Period, date: string) => period.from <= date && date <= period.to;
/** The period whose dates contain the date, or undefined when none does. */
export function periodOf(periods: Period[] | undefined, date: string): Period | undefined {
  return (periods ?? []).find((p) => contains(p, date));
}
/** A person's due-total for a period: once closed, the figure fixed on closing (0.00 for a person
 *  added since); else the sum of the figures of their claims that count whose date falls in it,
 *  skipping n/a. */
export function personPeriodDue(
  period: Period,
  person: Person,
  claims: Claim[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  if (period.closed) return period.people?.[String(person.id)] ?? '0.00';
  return dueTotal(
    live((claims ?? []).filter((c) => c.personId === person.id), [person])
      .filter((c) => counts(c) && contains(period, c.date))
      .map((c) => claimDue(c, rates, person.grades, floor, late)),
  );
}
/** A period's due-total as the list shows it: the sum of the people's due-totals for it. */
export function periodDue(
  period: Period,
  claims: Claim[] | undefined,
  people: Person[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  return dueTotal((people ?? []).map((p) => personPeriodDue(period, p, claims, rates, floor, late)));
}
=== features/settings/settings.ts
/** The sheet's settings: `clerkLimit` (two decimals) is the most due a clerk may settle a claim at,
 *  null for no limit; `floor` (two decimals) is the least a claim's live due may be; `terms` is the
 *  whole days after its date a claim is due by; `latePct` (two decimals) is the percent of an overdue
 *  claim's figure charged for every full 30 days it is overdue; `policyDate` (yyyy-MM-dd) is the date
 *  rounding turns on, null when blank (then the sheet's today); `periodNumberingFrom` (yyyy-MM-dd) is the
 *  date from which claims opened are numbered per period, null when blank (off); `gradeTerms` is the terms
 *  in force for each grade (its own, else the sheet's), by grade; `cap` (two decimals) is the most a person's
 *  due-total may be, null for no cap. Each of these that carries a figure is the one in force on the sheet's today.
 *  `floorFrom` and `latePctFrom` are the floor and late percent recorded, oldest from-date (yyyy-MM-dd) first:
 *  a claim's floor and late percent are those in force on its date. */
export type Settings = { clerkLimit: string | null; floor: string; terms: string; latePct: string; policyDate: string | null;
  periodNumberingFrom: string | null; gradeTerms: Record<string, string>; cap: string | null;
  floorFrom: Dated[]; latePctFrom: Dated[] };
/** A setting's value recorded from a date (yyyy-MM-dd); a null value is blank. */
export type Dated = { from: string; value: string | null };
/** The floor a sheet has before any is recorded. */
const STARTING_FLOOR = '1.00';
/** The late percent a sheet has before any is recorded. */
const STARTING_LATE_PCT = '0.00';
/** The value in force on the date: the one with the latest from-date on or before it, else `starting`. */
export function valueOn(history: Dated[], date: string, starting: string): string {
  let found: string | null = null;
  for (const d of history) if (d.from <= date) found = d.value;
  return found ?? starting;
}
/** The floor in force on each date; undefined until the settings are read. */
export function floorOf(settings: Settings | undefined): ((date: string) => string) | undefined {
  return settings && ((date) => valueOn(settings.floorFrom, date, STARTING_FLOOR));
}
/** The late percent in force on each date; undefined until the settings are read. */
export function latePctOf(settings: Settings | undefined): ((date: string) => string) | undefined {
  return settings && ((date) => valueOn(settings.latePctFrom, date, STARTING_LATE_PCT));
}
/** Under the sheet's key, so loading the sheet again re-reads its settings. */
export const settingsKey = (sheet: string) => [...sheetKey(sheet), 'settings'] as const;
export function useSettings(sheet: string) {
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    enabled: sheet !== '',
  });
}
